import { gql, useSubscription } from '@apollo/client';

const ON_NOTIFICATION = gql`
  subscription OnNotification {
    notificationReceived {
      id
      message
      read
    }
  }
`;

function NotificationPanel() {
  const [notifications, setNotifications] = useState([]);

  useSubscription(ON_NOTIFICATION, {
    onSubscriptionData: ({ subscriptionData }) => {
      const newNotification = subscriptionData.data.notificationReceived;
      setNotifications((prev) => [newNotification, ...prev]);
    },
    onError: (error) => {
      console.error('Subscription error:', error);
      // Show toast or fallback UI
    },
    onComplete: () => {
      console.log('Subscription stream closed by server');
    },
  });

  return <NotificationList items={notifications} />;
}

function LiveFeed() {
  // Subscription auto-starts on mount
  // Subscription auto-stops on unmount
  const { data } = useSubscription(ON_POST_ADDED, {
    variables: { categoryId: 'tech' },
  });

  return <PostCard post={data?.postAdded} />;
}

useSubscription(ON_CHAT_MESSAGE, {
  onError: (error) => {
    if (error.networkError) {
      showToast('Connection lost. Reconnecting...');
    } else if (error.graphQLErrors) {
      error.graphQLErrors.forEach((err) => {
        if (err.extensions?.code === 'FORBIDDEN') {
          showToast('You do not have access to this channel');
        }
      });
    }
  },
});

import { useState, useEffect } from 'react';
import { useSubscription } from '@apollo/client';

function useRetryableSubscription(query, variables, maxRetries = 3) {
  const [retryCount, setRetryCount] = useState(0);
  const [shouldRetry, setShouldRetry] = useState(true);

  const result = useSubscription(query, {
    variables,
    shouldResubscribe: shouldRetry,
    onError: (error) => {
      if (retryCount < maxRetries && error.networkError) {
        const delay = Math.pow(2, retryCount) * 1000;
        setTimeout(() => {
          setRetryCount((c) => c + 1);
          setShouldRetry(true);
        }, delay);
        setShouldRetry(false);
      }
    },
  });

  return result;
}
